"use client"

import * as React from "react"
import { DataTableRoot } from "@/components/niko-table/core/data-table-root"
import { DataTable } from "@/components/niko-table/core/data-table"
import {
  DataTableBody,
  DataTableEmptyBody,
  DataTableHeader,
} from "@/components/niko-table/core/data-table-structure"
import { useDataTable } from "@/components/niko-table/core/data-table-context"
import { DataTableColumnHeader } from "@/components/niko-table/components/data-table-column-header"
import { DataTableColumnTitle } from "@/components/niko-table/components/data-table-column-title"
import { DataTableColumnSortMenu } from "@/components/niko-table/components/data-table-column-sort"
import { DataTableToolbarSection } from "@/components/niko-table/components/data-table-toolbar-section"
import { DataTableSearchFilter } from "@/components/niko-table/components/data-table-search-filter"
import { DataTableFacetedFilter } from "@/components/niko-table/components/data-table-faceted-filter"
import { DataTableClearFilter } from "@/components/niko-table/components/data-table-clear-filter"
import { DataTableViewMenu } from "@/components/niko-table/components/data-table-view-menu"
import { DataTableExportButton } from "@/components/niko-table/components/data-table-export-button"
import { DataTableSelectionBar } from "@/components/niko-table/components/data-table-selection-bar"
import { DataTablePagination } from "@/components/niko-table/components/data-table-pagination"
import {
  DataTableEmptyDescription,
  DataTableEmptyFilteredMessage,
  DataTableEmptyIcon,
  DataTableEmptyMessage,
  DataTableEmptyTitle,
} from "@/components/niko-table/components/data-table-empty-state"
import {
  DataTableRowMenuScope,
  RowMenuItem,
  RowMenuSeparator,
  useDataTableRow,
} from "@/components/niko-table/components/data-table-row-menu"
import { DataTableRowContextMenuSlot } from "@/components/niko-table/components/data-table-row-context-menu-slot"
import { SYSTEM_COLUMN_IDS } from "@/components/niko-table/lib/constants"
import type { DataTableColumnDef } from "@/components/niko-table/types"
import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/niko-table/primitives/button"
import { Checkbox } from "@/components/niko-table/primitives/checkbox"
import { Progress } from "@/components/ui/progress"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/components/niko-table/primitives/dropdown-menu"
import {
  ArrowDownRight,
  ArrowUpRight,
  Globe2,
  Mail,
  MoreHorizontal,
  SearchX,
  UserPlus,
  Users,
} from "lucide-react"
import { cn } from "@/lib/utils"
import {
  customers as sampleCustomers,
  planOptions,
  statusOptions,
  type Customer,
} from "./customers-data"
import { formatDate, initials, money, statusDot } from "./customers-format"
import { CustomerSheet } from "./customer-sheet"
import { AddCustomerSheet, type NewCustomer } from "./add-customer-sheet"

/*
 * Row actions: one small piece per action, each reading its row from context.
 * `CustomersTable` composes them into ONE fragment that both the "⋯" dropdown
 * and the right-click menu render.
 */
function ViewCustomerItem({ onView }: { onView: (c: Customer) => void }) {
  const customer = useDataTableRow<Customer>()
  return (
    <RowMenuItem onClick={() => onView(customer)}>View customer</RowMenuItem>
  )
}

function CopyEmailItem({ onCopied }: { onCopied: (c: Customer) => void }) {
  const customer = useDataTableRow<Customer>()
  return (
    <RowMenuItem
      onClick={() => {
        void navigator.clipboard?.writeText(customer.email)
        onCopied(customer)
      }}
    >
      Copy email
    </RowMenuItem>
  )
}

function CancelSubscriptionItem({
  onCancel,
}: {
  onCancel: (c: Customer) => void
}) {
  const customer = useDataTableRow<Customer>()
  return (
    <RowMenuItem
      variant="destructive"
      disabled={customer.status === "churned"}
      onClick={() => onCancel(customer)}
    >
      Cancel subscription
    </RowMenuItem>
  )
}

function sortableHeader() {
  return (
    <DataTableColumnHeader>
      <DataTableColumnTitle />
      <DataTableColumnSortMenu />
    </DataTableColumnHeader>
  )
}

function useCustomerColumns(rowMenu: React.ReactNode) {
  return React.useMemo<DataTableColumnDef<Customer>[]>(
    () => [
      {
        id: SYSTEM_COLUMN_IDS.SELECT,
        size: 40,
        enableSorting: false,
        enableHiding: false,
        header: ({ table }) => (
          <Checkbox
            // Plain boolean: Radix and Base UI checkboxes take indeterminate differently.
            checked={table.getIsAllPageRowsSelected()}
            onCheckedChange={value => table.toggleAllPageRowsSelected(!!value)}
            aria-label="Select all customers on this page"
          />
        ),
        cell: ({ row }) => (
          <Checkbox
            checked={row.getIsSelected()}
            onCheckedChange={value => row.toggleSelected(!!value)}
            aria-label={`Select ${row.original.name}`}
          />
        ),
      },
      {
        accessorKey: "name",
        meta: { label: "Customer" },
        header: sortableHeader,
        cell: ({ row }) => (
          <div className="flex items-center gap-3">
            <Avatar className="size-8">
              <AvatarFallback className="text-xs">
                {initials(row.original.name)}
              </AvatarFallback>
            </Avatar>
            <div className="flex min-w-0 flex-col">
              <span className="truncate font-medium">{row.original.name}</span>
              <span className="truncate text-xs text-muted-foreground">
                {row.original.email}
              </span>
            </div>
          </div>
        ),
      },
      {
        accessorKey: "email",
        meta: { label: "Email" },
        // Searchable and exported, but shown under the name instead.
        enableHiding: false,
      },
      {
        accessorKey: "plan",
        meta: { label: "Plan", options: planOptions },
        header: sortableHeader,
        enableColumnFilter: true,
        cell: ({ row }) => (
          <Badge variant="secondary" className="capitalize">
            {row.original.plan}
          </Badge>
        ),
      },
      {
        accessorKey: "status",
        meta: { label: "Status", options: statusOptions },
        header: sortableHeader,
        enableColumnFilter: true,
        cell: ({ row }) => (
          <span className="flex items-center gap-2 capitalize">
            <span
              className={cn(
                "size-2 rounded-full",
                statusDot[row.original.status],
              )}
              aria-hidden="true"
            />
            {row.original.status}
          </span>
        ),
      },
      {
        accessorKey: "mrr",
        meta: { label: "MRR" },
        header: sortableHeader,
        cell: ({ row }) => {
          const { mrr, mrrChange, status } = row.original
          if (status !== "active") {
            return <span className="text-muted-foreground">—</span>
          }
          const up = mrrChange >= 0
          return (
            <div className="flex items-center gap-2 tabular-nums">
              <span className="font-medium">{money.format(mrr)}</span>
              <span
                className={cn(
                  "flex items-center text-xs",
                  up ? "text-success" : "text-destructive",
                )}
              >
                {up ? (
                  <ArrowUpRight className="size-3.5" aria-hidden="true" />
                ) : (
                  <ArrowDownRight className="size-3.5" aria-hidden="true" />
                )}
                <span className="sr-only">{up ? "Up" : "Down"}</span>
                {Math.abs(mrrChange)}%
              </span>
            </div>
          )
        },
      },
      {
        accessorKey: "seatsUsed",
        meta: { label: "Seats" },
        header: sortableHeader,
        cell: ({ row }) => {
          const { seatsUsed, seatsTotal } = row.original
          return (
            <div className="flex w-28 flex-col gap-1">
              <span className="text-xs text-muted-foreground tabular-nums">
                {seatsUsed} of {seatsTotal}
              </span>
              <Progress
                value={(seatsUsed / seatsTotal) * 100}
                className="h-1.5"
                aria-label={`${seatsUsed} of ${seatsTotal} seats used`}
              />
            </div>
          )
        },
      },
      {
        accessorKey: "signedUp",
        meta: { label: "Signed up" },
        header: sortableHeader,
        cell: ({ row }) => (
          <span className="text-muted-foreground tabular-nums">
            {formatDate(row.original.signedUp)}
          </span>
        ),
      },
      {
        accessorKey: "region",
        meta: { label: "Region" },
        header: sortableHeader,
        cell: ({ row }) => (
          <span className="flex items-center gap-2">
            <Globe2
              className="size-4 text-muted-foreground"
              aria-hidden="true"
            />
            {row.original.region}
          </span>
        ),
      },
      {
        id: "actions",
        size: 56,
        enableSorting: false,
        enableHiding: false,
        cell: ({ row }) => (
          <div className="flex justify-end">
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button
                  variant="ghost"
                  size="icon"
                  className="size-8"
                  aria-label={`Open actions for ${row.original.name}`}
                >
                  <MoreHorizontal className="size-4" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DataTableRowMenuScope row={row.original} surface="dropdown">
                  {rowMenu}
                </DataTableRowMenuScope>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        ),
      },
    ],
    [rowMenu],
  )
}

function CustomersHeader({ onAddCustomer }: { onAddCustomer: () => void }) {
  const { table } = useDataTable<Customer>()
  const rows = table.getFilteredRowModel().rows
  const mrr = rows.reduce((sum, row) => sum + row.original.mrr, 0)

  return (
    <div className="flex flex-wrap items-start justify-between gap-3">
      <div className="flex flex-col gap-0.5">
        <h2 className="text-base font-semibold">Customers</h2>
        <p className="text-sm text-muted-foreground">
          {rows.length} customers · {money.format(mrr)} MRR
        </p>
      </div>
      <div className="flex items-center gap-2">
        <DataTableExportButton filename="customers" useHeaderLabels />
        <Button size="sm" onClick={onAddCustomer}>
          <UserPlus className="size-4" aria-hidden="true" />
          Add customer
        </Button>
      </div>
    </div>
  )
}

function CustomersSelectionBar({
  onAction,
}: {
  onAction: (message: string) => void
}) {
  const { table } = useDataTable<Customer>()
  const selected = table.getFilteredSelectedRowModel().rows
  return (
    <DataTableSelectionBar
      selectedCount={selected.length}
      onClear={() => table.resetRowSelection()}
    >
      <Button
        size="sm"
        variant="outline"
        onClick={() => {
          onAction(`Emailed ${selected.length} customers`)
          table.resetRowSelection()
        }}
      >
        <Mail className="size-4" aria-hidden="true" />
        Email selected
      </Button>
    </DataTableSelectionBar>
  )
}

export default function CustomersTable() {
  const [customers, setCustomers] = React.useState(sampleCustomers)
  const [viewing, setViewing] = React.useState<Customer | null>(null)
  const [adding, setAdding] = React.useState(false)
  const [lastAction, setLastAction] = React.useState("")

  const cancelSubscription = React.useCallback((customer: Customer) => {
    const churned = {
      ...customer,
      status: "churned" as const,
      mrr: 0,
      mrrChange: 0,
      seatsUsed: 0,
    }
    setCustomers(rows =>
      rows.map(row => (row.id === customer.id ? churned : row)),
    )
    setViewing(current => (current?.id === customer.id ? churned : current))
    setLastAction(`Cancelled ${customer.name}'s subscription`)
  }, [])

  const addCustomer = React.useCallback((input: NewCustomer) => {
    setCustomers(rows => [
      {
        ...input,
        id: `cus_${(rows.length + 1).toString().padStart(3, "0")}`,
        status: "trial",
        mrr: 0,
        mrrChange: 0,
        seatsUsed: 1,
        signedUp: new Date(),
      },
      ...rows,
    ])
    setLastAction(`Added ${input.name} on a trial`)
  }, [])

  // The row actions, composed ONCE and mounted in both the "⋯" dropdown and
  // the right-click menu.
  const rowMenu = React.useMemo(
    () => (
      <>
        <ViewCustomerItem onView={setViewing} />
        <CopyEmailItem onCopied={c => setLastAction(`Copied ${c.email}`)} />
        <RowMenuSeparator />
        <CancelSubscriptionItem onCancel={cancelSubscription} />
      </>
    ),
    [cancelSubscription],
  )
  const columns = useCustomerColumns(rowMenu)

  return (
    <div className="w-full rounded-xl border bg-card p-4 text-card-foreground shadow-sm">
      <DataTableRoot
        data={customers}
        columns={columns}
        getRowId={row => row.id}
        initialState={{ columnVisibility: { email: false } }}
      >
        <div className="flex flex-col gap-4">
          <CustomersHeader onAddCustomer={() => setAdding(true)} />
          <DataTableToolbarSection className="flex-wrap px-0">
            <DataTableSearchFilter
              placeholder="Search customers..."
              className="min-w-48 flex-none sm:w-72"
            />
            <DataTableFacetedFilter accessorKey="status" multiple />
            <DataTableFacetedFilter accessorKey="plan" multiple />
            <DataTableClearFilter />
            <div className="ml-auto">
              <DataTableViewMenu />
            </div>
          </DataTableToolbarSection>
          <CustomersSelectionBar onAction={setLastAction} />
          <DataTable>
            <DataTableHeader />
            <DataTableBody<Customer> onRowClick={row => setViewing(row)}>
              <DataTableRowContextMenuSlot>
                {rowMenu}
              </DataTableRowContextMenuSlot>
              <DataTableEmptyBody>
                <DataTableEmptyMessage>
                  <DataTableEmptyIcon>
                    <Users className="size-12" />
                  </DataTableEmptyIcon>
                  <DataTableEmptyTitle>No customers yet</DataTableEmptyTitle>
                  <DataTableEmptyDescription>
                    Add your first customer to see them here.
                  </DataTableEmptyDescription>
                </DataTableEmptyMessage>
                <DataTableEmptyFilteredMessage>
                  <DataTableEmptyIcon>
                    <SearchX className="size-12" />
                  </DataTableEmptyIcon>
                  <DataTableEmptyTitle>
                    No matching customers
                  </DataTableEmptyTitle>
                  <DataTableEmptyDescription>
                    Try a different search or clear the filters.
                  </DataTableEmptyDescription>
                </DataTableEmptyFilteredMessage>
              </DataTableEmptyBody>
            </DataTableBody>
          </DataTable>
          <DataTablePagination />
          {lastAction && (
            <p className="text-xs text-muted-foreground" aria-live="polite">
              {lastAction}
            </p>
          )}
        </div>
      </DataTableRoot>
      <CustomerSheet
        customer={viewing}
        onOpenChange={open => !open && setViewing(null)}
        onCancelSubscription={cancelSubscription}
      />
      <AddCustomerSheet
        open={adding}
        onOpenChange={setAdding}
        onAdd={addCustomer}
      />
    </div>
  )
}

import type { CustomerStatus } from "./customers-data"

export const money = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  maximumFractionDigits: 0,
})

const shortDate = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
  timeZone: "UTC",
})

export function formatDate(date: Date) {
  return shortDate.format(date)
}

export const statusDot: Record<CustomerStatus, string> = {
  active: "bg-success",
  trial: "bg-warning",
  churned: "bg-muted-foreground",
}

export function initials(name: string) {
  return name
    .split(" ")
    .filter(Boolean)
    .map(part => part[0]?.toUpperCase())
    .slice(0, 2)
    .join("")
}

"use client"

import * as React from "react"
import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/niko-table/primitives/button"
import { Progress } from "@/components/ui/progress"
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
} from "@/components/niko-table/primitives/sheet"
import { Check, Copy, Mail } from "lucide-react"
import { cn } from "@/lib/utils"
import type { Customer } from "./customers-data"
import { formatDate, initials, money, statusDot } from "./customers-format"

function DetailRow({
  label,
  children,
}: {
  label: string
  children: React.ReactNode
}) {
  return (
    <div className="flex items-center justify-between gap-4 py-2 text-sm">
      <dt className="text-muted-foreground">{label}</dt>
      <dd className="text-right">{children}</dd>
    </div>
  )
}

function DetailSection({
  title,
  children,
}: {
  title: string
  children: React.ReactNode
}) {
  return (
    <section className="flex flex-col gap-1">
      <h3 className="text-xs font-medium tracking-wide text-muted-foreground uppercase">
        {title}
      </h3>
      <dl className="divide-y">{children}</dl>
    </section>
  )
}

function CopyButton({ value, label }: { value: string; label: string }) {
  const [copied, setCopied] = React.useState(false)
  return (
    <Button
      variant="ghost"
      size="icon"
      className="size-6"
      aria-label={label}
      onClick={() => {
        void navigator.clipboard?.writeText(value)
        setCopied(true)
        setTimeout(() => setCopied(false), 1500)
      }}
    >
      {copied ? <Check className="size-3.5" /> : <Copy className="size-3.5" />}
    </Button>
  )
}

/** Side panel with one customer's details. Opens on row click. */
export function CustomerSheet({
  customer,
  onOpenChange,
  onCancelSubscription,
}: {
  customer: Customer | null
  onOpenChange: (open: boolean) => void
  onCancelSubscription: (customer: Customer) => void
}) {
  return (
    <Sheet open={customer !== null} onOpenChange={onOpenChange}>
      <SheetContent className="flex w-full flex-col gap-0 sm:max-w-md">
        {customer && (
          <>
            <SheetHeader className="flex-row items-center gap-3 border-b">
              <Avatar className="size-10">
                <AvatarFallback>{initials(customer.name)}</AvatarFallback>
              </Avatar>
              <div className="flex min-w-0 flex-col">
                <SheetTitle className="truncate">{customer.name}</SheetTitle>
                <SheetDescription className="flex items-center gap-2 capitalize">
                  <span
                    className={cn(
                      "size-2 rounded-full",
                      statusDot[customer.status],
                    )}
                    aria-hidden="true"
                  />
                  {customer.status} · {customer.plan} plan
                </SheetDescription>
              </div>
            </SheetHeader>

            <div className="flex flex-1 flex-col gap-6 overflow-y-auto p-4">
              <DetailSection title="Subscription">
                <DetailRow label="Plan">
                  <Badge variant="secondary" className="capitalize">
                    {customer.plan}
                  </Badge>
                </DetailRow>
                <DetailRow label="MRR">
                  <span className="tabular-nums">
                    {customer.status === "active"
                      ? `${money.format(customer.mrr)} (${customer.mrrChange >= 0 ? "+" : ""}${customer.mrrChange}%)`
                      : "—"}
                  </span>
                </DetailRow>
                <DetailRow label="Seats">
                  <div className="flex w-36 flex-col items-end gap-1">
                    <span className="tabular-nums">
                      {customer.seatsUsed} of {customer.seatsTotal} used
                    </span>
                    <Progress
                      value={(customer.seatsUsed / customer.seatsTotal) * 100}
                      className="h-1.5"
                      aria-label="Seats used"
                    />
                  </div>
                </DetailRow>
                <DetailRow label="Customer since">
                  {formatDate(customer.signedUp)}
                </DetailRow>
              </DetailSection>

              <DetailSection title="Account">
                <DetailRow label="Customer ID">
                  <span className="flex items-center gap-1 font-mono text-xs">
                    {customer.id}
                    <CopyButton value={customer.id} label="Copy customer ID" />
                  </span>
                </DetailRow>
                <DetailRow label="Email">{customer.email}</DetailRow>
                <DetailRow label="Region">{customer.region}</DetailRow>
              </DetailSection>
            </div>

            <SheetFooter className="flex-row justify-between border-t">
              <Button
                variant="outline"
                size="sm"
                disabled={customer.status === "churned"}
                onClick={() => onCancelSubscription(customer)}
              >
                Cancel subscription
              </Button>
              <Button size="sm" asChild>
                <a href={`mailto:${customer.email}`}>
                  <Mail className="size-4" aria-hidden="true" />
                  Email
                </a>
              </Button>
            </SheetFooter>
          </>
        )}
      </SheetContent>
    </Sheet>
  )
}

"use client"

/**
 * Niko Table's dropdown-menu primitive, React Aria build. Radix-shaped API
 * (`DropdownMenuTrigger asChild`, `DropdownMenuContent align side`, items with
 * `onClick` / `disabled` / `variant`, submenus, radio groups) on top of
 * `react-aria-components` `MenuTrigger` / `Pressable` and the React Aria shadcn
 * dropdown-menu pieces (a React Aria `Menu` in a `Popover`).
 *
 * A React Aria menu is a collection: only items, labels, separators, groups
 * and submenus render inside it. Wrap any other content in
 * `DropdownMenuPanel`, which renders it as a non-focusable menu node.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import {
  Header,
  MenuTrigger,
  OverlayTriggerStateContext,
  Pressable,
  type Placement,
  type PressEvent,
} from "react-aria-components"

import {
  DropdownMenu as MenuPopover,
  DropdownMenuGroup,
  DropdownMenuItem as MenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent as SubmenuPopover,
  DropdownMenuSubTrigger as SubmenuItem,
} from "@/components/ui/dropdown-menu"

type Side = "top" | "right" | "bottom" | "left"
type Align = "start" | "center" | "end"
type PressableChild = React.ComponentProps<typeof Pressable>["children"]

function toPlacement(side: Side, align: Align): Placement {
  if (align === "center") return side
  if (side === "top" || side === "bottom") return `${side} ${align}`
  return `${side} ${align === "start" ? "top" : "bottom"}`
}

/** Plain text of a node tree, for React Aria's type-to-select. */
function textOf(node: React.ReactNode): string {
  if (typeof node === "string" || typeof node === "number") return String(node)
  if (Array.isArray(node)) return node.map(textOf).join("")
  if (React.isValidElement<{ children?: React.ReactNode }>(node))
    return textOf(node.props.children)
  return ""
}

function DropdownMenu({
  open,
  defaultOpen,
  onOpenChange,
  children,
}: {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Radix option; React Aria menus are always modal. */
  modal?: boolean
  children?: React.ReactNode
}) {
  return (
    <MenuTrigger
      isOpen={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      {children}
    </MenuTrigger>
  )
}

function DropdownMenuTrigger({
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> & { asChild?: boolean }) {
  const isOpen = React.useContext(OverlayTriggerStateContext)?.isOpen ?? false
  const state = { "data-state": isOpen ? "open" : "closed" }
  // Slot: MenuTrigger hands its press, keyboard and aria props to the child;
  // the trigger's own props merge onto it.
  const child =
    asChild && React.isValidElement<object>(children) ? (
      React.cloneElement(children, mergeProps(children.props, props, state))
    ) : (
      <button type="button" {...props} {...state}>
        {children}
      </button>
    )
  // A host element (a plain <button>, <a>) cannot take React Aria's press
  // itself, so Pressable gives it one. A component child (the Button
  // primitive, shadcn's Button) takes it directly; wrapping it too would
  // register the press twice.
  return typeof child.type === "string" ? (
    <Pressable>{child as PressableChild}</Pressable>
  ) : (
    child
  )
}

function DropdownMenuContent({
  align = "center",
  side = "bottom",
  sideOffset = 4,
  alignOffset = 0,
  className,
  children,
}: {
  align?: Align
  side?: Side
  sideOffset?: number
  alignOffset?: number
  className?: string
  children?: React.ReactNode
}) {
  return (
    <MenuPopover
      placement={toPlacement(side, align)}
      offset={sideOffset}
      crossOffset={alignOffset}
      className={className}
    >
      {children}
    </MenuPopover>
  )
}

interface DropdownMenuItemProps {
  /** Runs on pointer and keyboard activation; the press event carries `shiftKey`. */
  onClick?: (event: PressEvent) => void
  disabled?: boolean
  variant?: "default" | "destructive"
  inset?: boolean
  textValue?: string
  className?: string
  children?: React.ReactNode
}

function DropdownMenuItem({
  onClick,
  disabled,
  textValue,
  children,
  ...props
}: DropdownMenuItemProps) {
  return (
    <MenuItem
      {...props}
      onPress={onClick}
      isDisabled={disabled}
      textValue={textValue ?? textOf(children)}
    >
      {children}
    </MenuItem>
  )
}

function DropdownMenuSubTrigger({
  disabled,
  textValue,
  children,
  ...props
}: Omit<DropdownMenuItemProps, "onClick" | "variant">) {
  return (
    <SubmenuItem
      {...props}
      isDisabled={disabled}
      textValue={textValue ?? textOf(children)}
    >
      {children}
    </SubmenuItem>
  )
}

function DropdownMenuSubContent({
  sideOffset,
  alignOffset,
  className,
  children,
}: {
  className?: string
  children?: React.ReactNode
  sideOffset?: number
  alignOffset?: number
}) {
  return (
    <SubmenuPopover
      // Unset keeps the shadcn aria submenu defaults.
      {...(sideOffset === undefined ? {} : { offset: sideOffset })}
      {...(alignOffset === undefined ? {} : { crossOffset: alignOffset })}
      className={className}
    >
      {children}
    </SubmenuPopover>
  )
}

function DropdownMenuRadioGroup({
  value,
  onValueChange,
  children,
}: {
  value?: string
  onValueChange?: (value: string) => void
  children?: React.ReactNode
}) {
  return (
    <DropdownMenuGroup
      selectionMode="single"
      disallowEmptySelection
      selectedKeys={value === undefined ? [] : [value]}
      onSelectionChange={keys => {
        if (keys === "all") return
        const [key] = keys
        if (key !== undefined) onValueChange?.(String(key))
      }}
    >
      {children}
    </DropdownMenuGroup>
  )
}

function DropdownMenuRadioItem({
  value,
  disabled,
  textValue,
  children,
  ...props
}: Omit<DropdownMenuItemProps, "onClick" | "variant"> & { value: string }) {
  return (
    <MenuItem
      {...props}
      id={value}
      isDisabled={disabled}
      textValue={textValue ?? textOf(children)}
    >
      {children}
    </MenuItem>
  )
}

function stopMenuKeys(event: React.KeyboardEvent) {
  // Keep typing / arrows inside the panel's own controls; Escape still closes.
  if (event.key !== "Escape") event.stopPropagation()
}

function DropdownMenuPanel({ children }: { children: React.ReactNode }) {
  return (
    <Header
      role="presentation"
      onKeyDown={stopMenuKeys}
      onKeyUp={stopMenuKeys}
      // The menu moves focus to its first item when focus enters it.
      onFocus={event => event.stopPropagation()}
    >
      {children}
    </Header>
  )
}

export {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuPanel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
}

