/**
 * Niko Table's button primitive, React Aria build: shadcn's React Aria
 * `Button` behind the Radix `Button` API Niko Table calls it with (native
 * `<button>` props, `variant`, `size`, `asChild`).
 *
 * - `onClick` goes to React Aria's `onClick`, its alias of `onPress`: a real
 *   MouseEvent on click and a synthesized click for keyboard and screen-reader
 *   presses, so `stopPropagation()` / `shiftKey` keep working.
 * - `disabled` becomes `isDisabled`.
 * - Everything else (title, tabIndex, role, aria-*, key and mouse handlers) goes
 *   on the `<button>` through React Aria's `render`, as on a native button.
 *   React Aria's Button would drop those attributes and stop key events.
 *
 * Overlay triggers (`PopoverTrigger asChild` and the rest) hand their press to
 * this button, so an `asChild` trigger's child must be this Button (or
 * shadcn's), as with shadcn's own React Aria triggers.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import type { VariantProps } from "class-variance-authority"

import {
  Button as ButtonPrimitive,
  buttonVariants,
} from "@/components/ui/button"
import { cn } from "@/lib/utils"

type OnPressClick = React.ComponentProps<typeof ButtonPrimitive>["onClick"]

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  if (
    asChild &&
    React.isValidElement<React.HTMLAttributes<HTMLElement>>(children)
  ) {
    // Slot: the child element is the button (e.g. a link styled as one); its
    // own handlers and refs compose with the button's.
    return React.cloneElement(children, {
      ...mergeProps(children.props, { "data-slot": "button" }, props),
      className: cn(
        buttonVariants({ variant, size }),
        className,
        children.props.className,
      ),
    } as React.HTMLAttributes<HTMLElement>)
  }

  const { ref, id, type, slot, disabled, onClick, onMouseDown, ...native } =
    props
  return (
    <ButtonPrimitive
      ref={ref}
      id={id}
      type={type}
      slot={slot}
      variant={variant}
      size={size}
      className={className}
      isDisabled={disabled}
      onClick={onClick as OnPressClick}
      render={domProps => (
        <button
          {...mergeProps(domProps, native)}
          onMouseDown={event => {
            // React Aria's press handler stops every left mousedown; a native
            // button lets it bubble (the grid selects cells on mousedown).
            event.stopPropagation = () => {}
            domProps.onMouseDown?.(event)
            delete (event as Partial<typeof event>).stopPropagation
            onMouseDown?.(event)
          }}
        />
      )}
    >
      {children}
    </ButtonPrimitive>
  )
}

export { Button, buttonVariants }

"use client"

/**
 * Niko Table's select primitive, React Aria build. Radix-shaped API
 * (`Select value onValueChange open onOpenChange disabled`, `SelectTrigger`,
 * `SelectValue placeholder`, `SelectContent`, `SelectItem value`) on top of the
 * React Aria shadcn select (a React Aria `Select` with a `ListBox`).
 */
import * as React from "react"

import {
  Select as SelectRoot,
  SelectContent as SelectPopover,
  SelectItem as SelectOption,
  SelectTrigger as SelectButton,
  SelectValue as SelectValuePrimitive,
} from "@/components/ui/select"

/** Plain text of a node tree, for React Aria's type-to-select. */
function textOf(node: React.ReactNode): string {
  if (typeof node === "string" || typeof node === "number") return String(node)
  if (Array.isArray(node)) return node.map(textOf).join("")
  if (React.isValidElement<{ children?: React.ReactNode }>(node))
    return textOf(node.props.children)
  return ""
}

function Select({
  value,
  defaultValue,
  onValueChange,
  open,
  onOpenChange,
  disabled,
  required,
  name,
  children,
}: {
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  open?: boolean
  onOpenChange?: (open: boolean) => void
  disabled?: boolean
  required?: boolean
  name?: string
  children?: React.ReactNode
}) {
  // React Aria labels the select on its root; Radix call sites label the
  // trigger, so lift the trigger's aria-label / aria-labelledby. Only a
  // direct-child SelectTrigger is found; a wrapped one leaves it unlabelled.
  const trigger = React.Children.toArray(children).find(
    (child): child is React.ReactElement<SelectTriggerProps> =>
      React.isValidElement(child) && child.type === SelectTrigger,
  )
  return (
    <SelectRoot
      aria-label={trigger?.props["aria-label"]}
      aria-labelledby={trigger?.props["aria-labelledby"]}
      value={value}
      defaultValue={defaultValue}
      onChange={key => {
        if (key !== null) onValueChange?.(String(key))
      }}
      isOpen={open}
      onOpenChange={onOpenChange}
      isDisabled={disabled}
      isRequired={required}
      name={name}
    >
      {children}
    </SelectRoot>
  )
}

interface SelectTriggerProps {
  className?: string
  size?: "sm" | "default"
  id?: string
  title?: string
  children?: React.ReactNode
  /** Read by `Select`, which labels the React Aria select with it. */
  "aria-label"?: string
  /** Read by `Select`, which labels the React Aria select with it. */
  "aria-labelledby"?: string
  /** Radix wiring; React Aria links the trigger to its list itself. */
  "aria-controls"?: string
}

function SelectTrigger({
  className,
  size,
  id,
  title,
  children,
}: SelectTriggerProps) {
  return (
    <SelectButton className={className} size={size} id={id}>
      {/* React Aria's button takes no `title`; keep the hint on its content. */}
      <span title={title} className="contents">
        {children}
      </span>
    </SelectButton>
  )
}

function SelectValue({
  placeholder,
  className,
}: {
  placeholder?: React.ReactNode
  className?: string
}) {
  return (
    <SelectValuePrimitive className={className}>
      {({ isPlaceholder, defaultChildren }) =>
        isPlaceholder ? placeholder : defaultChildren
      }
    </SelectValuePrimitive>
  )
}

function SelectContent({
  className,
  children,
}: {
  className?: string
  children?: React.ReactNode
  /** Radix wiring; React Aria links the trigger to its list itself. */
  id?: string
  /** Radix option; ignored, React Aria always positions as a popover. */
  position?: "popper" | "item-aligned"
}) {
  return <SelectPopover className={className}>{children}</SelectPopover>
}

function SelectItem({
  value,
  disabled,
  className,
  children,
}: {
  value: string
  disabled?: boolean
  className?: string
  children?: React.ReactNode
}) {
  return (
    <SelectOption
      id={value}
      isDisabled={disabled}
      className={className}
      textValue={textOf(children) || value}
    >
      {children}
    </SelectOption>
  )
}

export { Select, SelectContent, SelectItem, SelectTrigger, SelectValue }

"use client"

/**
 * Niko Table's checkbox primitive, React Aria build. Radix-shaped API
 * (`checked` incl. "indeterminate", `onCheckedChange`, `disabled`) on top of
 * the React Aria shadcn `Checkbox`.
 */
import * as React from "react"

import { Checkbox as CheckboxPrimitive } from "@/components/ui/checkbox"

function Checkbox({
  checked,
  defaultChecked,
  onCheckedChange,
  disabled,
  tabIndex,
  ...props
}: Omit<
  React.ComponentProps<typeof CheckboxPrimitive>,
  | "isSelected"
  | "defaultSelected"
  | "isIndeterminate"
  | "onChange"
  | "isDisabled"
> & {
  checked?: boolean | "indeterminate"
  defaultChecked?: boolean
  onCheckedChange?: (checked: boolean) => void
  disabled?: boolean
  /** -1 takes the checkbox out of the tab order (e.g. inside a grid cell). */
  tabIndex?: number
}) {
  return (
    <CheckboxPrimitive
      {...props}
      excludeFromTabOrder={tabIndex === -1}
      isSelected={checked === undefined ? undefined : checked === true}
      isIndeterminate={checked === "indeterminate"}
      defaultSelected={defaultChecked}
      onChange={onCheckedChange}
      isDisabled={disabled}
    />
  )
}

export { Checkbox }

"use client"

/**
 * Niko Table's sheet primitive, React Aria build. Radix-shaped API
 * (`Sheet open onOpenChange`, `SheetClose asChild`, `SheetContent`) on
 * shadcn's React Aria `Sheet` (a React Aria modal, which owns focus and
 * dismissal) in its controlled form. Niko Table opens sheets only through
 * `open`, so there is no `SheetTrigger` and no React Aria `DialogTrigger`.
 *
 * `SheetClose asChild`: the Button primitive (or shadcn's Button) closes
 * through React Aria's `slot="close"`, a plain element through `Pressable`.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import { OverlayTriggerStateContext, Pressable } from "react-aria-components"

import {
  Sheet as SheetModal,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet"

type PressableChild = React.ComponentProps<typeof Pressable>["children"]
type OpenProps = {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
}

/** Root props, read by `SheetContent`. */
const SheetContext = React.createContext<OpenProps>({})

function Sheet({
  open,
  defaultOpen,
  onOpenChange,
  children,
}: OpenProps & { children?: React.ReactNode }) {
  return (
    <SheetContext.Provider value={{ open, defaultOpen, onOpenChange }}>
      {children}
    </SheetContext.Provider>
  )
}

/** Slot for a close button: React Aria's Dialog closes on `slot="close"`. */
function SheetClose({
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> & { asChild?: boolean }) {
  const state = React.useContext(OverlayTriggerStateContext)
  const child =
    asChild && React.isValidElement<object>(children) ? (
      React.cloneElement(
        children,
        mergeProps(children.props, props, { slot: "close" }),
      )
    ) : (
      <button type="button" {...props}>
        {children}
      </button>
    )
  // A host element cannot take React Aria's press itself; Pressable gives it
  // one. A component child closes through `slot="close"`.
  return typeof child.type === "string" ? (
    <Pressable onPress={() => state?.close()}>
      {child as PressableChild}
    </Pressable>
  ) : (
    child
  )
}

function SheetContent({
  className,
  children,
  showCloseButton = true,
  side = "right",
}: {
  className?: string
  children?: React.ReactNode
  showCloseButton?: boolean
  side?: "top" | "right" | "bottom" | "left"
}) {
  const { open, defaultOpen, onOpenChange } = React.useContext(SheetContext)
  return (
    <SheetModal
      isOpen={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
      side={side}
      className={className}
      showCloseButton={showCloseButton}
    >
      {children}
    </SheetModal>
  )
}

export {
  Sheet,
  SheetClose,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
}
